import { motion } from "framer-motion";
import { galleryImages } from "../data/gallery";

const transforms = [
  "translateZ(120px) scale(12.1)",
  "translateZ(70px) scale(0.95)",
  "translateZ(0px) scale(0.82)",
  "translateZ(0px) scale(0.82)",
  "translateZ(70px) scale(0.95)",
  "translateZ(200px) scale(1.1)"
];

export default function HorizontalGallery() {
  return (
    <div
      className="
    absolute
    left-1/2
    top-[180px]
    -translate-x-1/2
    w-[2400px]
    overflow-hidden
    z-0
  ">
      <motion.div
        className="flex items-center -space-x-6"
        animate={{
          x: ["0%", "-50%"]
        }}
        style={{
          perspective: "2200px",
          transformStyle: "preserve-3d"
        }}
        transition={{
          duration: 28,
          repeat: Infinity,
          ease: "linear"
        }}>
        {[...galleryImages, ...galleryImages].map((item, index) => (
          <motion.div
            //   key={index}
            whileHover={{
              scale: 1.08
            }}
            style={{
              transform: transforms[index % transforms.length]
            }}
            className="
w-[430px]
h-[240px]
overflow-hidden
border
border-white/5
shadow-2xl
flex-shrink-0
">
            <img
              src={item.image}
              className="w-full h-full object-cover"
              alt=""
            />
          </motion.div>
        ))}
      </motion.div>
    </div>
  );
}
